package service;

import domain.RefundLine;
import domain.RunResult;
import infra.PgsimClient;
import infra.RefundFileWriter;
import store.RefundRepository;

import java.nio.file.Path;
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Nightly refund run: every pending refund line goes to the PG in batches of
 * at most maxLines. Batch id = run id + chunk number; the PG settles and is
 * reconciled per batch id.
 */
public class RefundBatchJob {
    private final RefundRepository refunds;
    private final PgsimClient pg;
    private final String mid;
    private final String prefix;
    private final int maxLines;
    private final Path workDir;

    public RefundBatchJob(RefundRepository refunds, PgsimClient pg, String mid, String prefix, int maxLines,
                          Path workDir) {
        this.refunds = refunds;
        this.pg = pg;
        this.mid = mid;
        this.prefix = prefix;
        this.maxLines = maxLines;
        this.workDir = workDir;
    }

    public RunResult run(LocalDate day) {
        String runId = String.format("%s%s-%02d", prefix, day.format(DateTimeFormatter.BASIC_ISO_DATE),
                refunds.nextRunSeq());
        List<RefundLine> pending = uniquePending();
        List<String> batchIds = new ArrayList<>();
        int completed = 0;
        for (int start = 0, chunk = 1; start < pending.size(); start += maxLines, chunk++) {
            List<RefundLine> part = pending.subList(start, Math.min(pending.size(), start + maxLines));
            String batchId = runId + "-" + chunk;
            Path file = RefundFileWriter.write(workDir, batchId, part);
            int accepted = pg.refund(mid, batchId, file);
            if (accepted != part.size()) {
                throw new IllegalStateException("PG accepted " + accepted + " of " + part.size() + " in " + batchId);
            }
            for (RefundLine l : part) l.submitted(batchId);
            batchIds.add(batchId);
            completed += RefundResultMatcher.apply(part, pg.status(batchId));
        }
        int awaiting = (int) pending.stream().filter(l -> l.status() == RefundLine.Status.SUBMITTED).count();
        return new RunResult(runId, List.copyOf(batchIds), pending.size(), completed, awaiting);
    }

    /** A line queued twice by a CS double-click must be refunded once. */
    private List<RefundLine> uniquePending() {
        Map<String, RefundLine> byKey = new LinkedHashMap<>();
        for (RefundLine l : refunds.pending()) {
            byKey.putIfAbsent(l.orderNo() + "#" + l.lineNo(), l);
        }
        return new ArrayList<>(byKey.values());
    }
}
package service;

import domain.RefundLine;
import infra.PgsimClient.RefundRow;
import infra.RefundFileWriter;

import java.util.ArrayList;
import java.util.List;

/** Attaches PG refund numbers from a batch status to the lines we sent in that batch. */
public final class RefundResultMatcher {
    private RefundResultMatcher() {}

    /** Returns how many lines got a refund number. Each PG row is used at most once. */
    public static int apply(List<RefundLine> sent, List<RefundRow> rows) {
        List<RefundRow> free = new ArrayList<>(rows);
        int matched = 0;
        for (RefundLine line : sent) {
            String ref = RefundFileWriter.merchantRef(line);
            for (int i = 0; i < free.size(); i++) {
                RefundRow row = free.get(i);
                if (row.tid().equals(line.tid()) && row.amount() == line.amount() && row.aux().equals(ref)) {
                    line.done(row.refundNo());
                    free.remove(i);
                    matched++;
                    break;
                }
            }
        }
        return matched;
    }
}
package service;

import domain.Order;
import domain.OrderLine;
import domain.RefundLine;
import store.OrderRepository;
import store.RefundRepository;

import java.time.LocalDate;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

/** CS side: accepts a (partial) refund request. Money moves in the nightly refund run. */
public class RefundService {
    private final OrderRepository orders;
    private final RefundRepository refunds;

    public RefundService(OrderRepository orders, RefundRepository refunds) {
        this.orders = orders;
        this.refunds = refunds;
    }

    public String request(String orderNo, List<Integer> lineNos, LocalDate day) {
        Order order = orders.find(orderNo).orElseThrow(() -> new IllegalArgumentException("no order " + orderNo));
        if (lineNos.isEmpty()) throw new IllegalArgumentException("no lines to refund");
        Set<Integer> wanted = new LinkedHashSet<>(lineNos);
        if (wanted.size() != lineNos.size()) throw new IllegalArgumentException("line listed twice");
        Set<Integer> taken = new LinkedHashSet<>();
        for (RefundLine r : refunds.byOrder(orderNo)) taken.add(r.lineNo());
        for (int n : wanted) {
            order.line(n);
            if (taken.contains(n)) throw new IllegalStateException("line " + n + " of " + orderNo + " already refunded");
        }
        String id = refunds.nextRequestId();
        for (int n : wanted) {
            OrderLine line = order.line(n);
            refunds.add(new RefundLine(id, orderNo, n, order.tid(), line.paid(), day));
        }
        return id;
    }
}
